function fewestSplits(nums: number[]): number {
  const memo = new Map<string, number>();
  // cheapest moves for nums[0..i] when nums[i]'s pieces must be <= cap
  const go = (i: number, cap: number): number => {
    if (i < 0) return 0;
    const key = i + "," + cap;
    if (memo.has(key)) return memo.get(key)!;
    const v = nums[i];
    let best = Infinity;
    for (let k = Math.ceil(v / cap); k <= v; k++) best = Math.min(best, k - 1 + go(i - 1, Math.floor(v / k)));
    memo.set(key, best);
    return best;
  };
  return go(nums.length - 1, nums[nums.length - 1]);
}

