        def go(i, cap):
            # cheapest moves for nums[0..i] when nums[i]'s pieces must be <= cap
            if i < 0:
                return 0
            v = nums[i]
            return min(k - 1 + go(i - 1, v // k) for k in range(-(-v // cap), v + 1))

        return go(len(nums) - 1, nums[-1])

