function fewestSplits(nums: number[]): number {
  let cap = nums[nums.length - 1], moves = 0;
  for (let i = nums.length - 2; i >= 0; i--) {
    const v = nums[i];
    if (v <= cap) { cap = v; continue; }
    const k = Math.ceil(v / cap);
    moves += k - 1;
    cap = Math.floor(v / k); // smallest piece of the most even split
  }
  return moves;
}

